def describe(rel):
    parts = rel.split("/")
    for n in range(len(parts), 0, -1):
        key = "/".join(parts[-n:])
        if key in DESC:
            return DESC[key]
    return ""


# ---------------------------------------------------------------------------------------------------------------
# what a file is
# ---------------------------------------------------------------------------------------------------------------
def human(n):
    for unit, d in (("GB", 1e9), ("MB", 1e6), ("KB", 1e3)):
        if n >= d:
            return f"{n / d:.1f} {unit}"
    return f"{n} B"


def probe(path):
    try:
        out = subprocess.run(["ffprobe", "-v", "error", "-show_entries", "format=duration:stream=codec_type,codec_name,width,height,r_frame_rate,sample_rate,channels,pix_fmt",
                              "-of", "json", str(path)], capture_output=True, text=True, timeout=60).stdout
        j = json.loads(out)
    except Exception:
        return ""
    dur = float(j.get("format", {}).get("duration", 0) or 0)
    v = next((s for s in j.get("streams", []) if s.get("codec_type") == "video"), None)
    a = next((s for s in j.get("streams", []) if s.get("codec_type") == "audio"), None)
    bits = [f"{dur:.1f} s"]
    if v:
        num, den = (v.get("r_frame_rate") or "0/1").split("/")
        fps = float(num) / max(1.0, float(den))
        codec = {"h264": "H.264", "prores": "ProRes 4444" if "a" in (v.get("pix_fmt") or "")[:5] else "ProRes"}.get(v.get("codec_name"), v.get("codec_name"))
        bits.append(f"{v.get('width')} x {v.get('height')}, {fps:g} fps, {codec}")
        if "yuva" in (v.get("pix_fmt") or ""):
            bits.append("transparent")
    if a:
        bits.append(f"sound {int(a.get('sample_rate', 0)) // 1000} kHz")
    return ", ".join(bits)


def details(path):
    ext = path.suffix.lower()
    try:
        if ext in (".png", ".jpg", ".jpeg"):
            with Image.open(path) as im:
                w, h = im.size
                alpha = im.mode in ("RGBA", "LA") or (im.mode == "P" and "transparency" in im.info)
                dpi = im.info.get("dpi")
            s = f"{w} x {h} px"
            if dpi and round(dpi[0]) >= 150:
                s += f", {round(dpi[0])} dpi"
            return s + (", transparent" if alpha else "")
        if ext in (".mp4", ".mov"):
            return probe(path)
        if ext == ".wav":
            with wave.open(str(path)) as w:
                return f"{w.getnframes() / w.getframerate():.1f} s, {w.getframerate() // 1000} kHz, {8 * w.getsampwidth()}-bit, {'stereo' if w.getnchannels() == 2 else 'mono'}"
        if ext == ".pdf":
            from pypdf import PdfReader
            r = PdfReader(str(path))
            box = r.pages[0].mediabox
            return f"{len(r.pages)} page{'s' if len(r.pages) > 1 else ''}, {float(box.width) * 25.4 / 72:.0f} x {float(box.height) * 25.4 / 72:.0f} mm"
        if ext == ".svg":
            head = path.read_text(errors="ignore")[:600]
            if 'viewBox="' in head:
                return "vector, viewBox " + head.split('viewBox="')[1].split('"')[0]
            return "vector"
        if ext == ".cube":
            return "33-point 3D colour look"
        if ext == ".ico":
            return "icon: 16, 32 and 48 px"
        if ext == ".zip":
            return "zip archive"
    except Exception as e:                       # a file that can't be read is reported, not hidden
        return f"(could not read: {type(e).__name__})"
    return ""


# ---------------------------------------------------------------------------------------------------------------
def walk():
    """All folders (sorted) -> their files and subfolders, skipping work files."""
    out = {}
    for d in sorted([KIT] + [p for p in KIT.rglob("*") if p.is_dir()]):
        rel = d.relative_to(KIT)
        if any(part in SKIP_DIRS for part in rel.parts) or str(rel).startswith("downloads"):
            if not str(rel) == "downloads":
                continue
        files = sorted([f for f in d.iterdir() if f.is_file() and f.name != ".DS_Store"], key=lambda p: p.name)
        subs = sorted([s for s in d.iterdir() if s.is_dir() and s.name not in SKIP_DIRS], key=lambda p: p.name)
        out[d] = (files, subs)
    return out


def write_readme(d, files, subs, cache):
    rel = "" if d == KIT else str(d.relative_to(KIT))
    rd = d / "README.md"
    if rd.exists() and not rd.read_text(errors="ignore").startswith(MARK):
        return False                                             # hand-written: leave it alone
    title = d.name if rel else "ASTRIS PRODUCTIONS brand kit"
    style = next((STYLE_DIRS[p] for p in d.relative_to(KIT).parts if p in STYLE_DIRS), None) if rel else None
    lines = [MARK, f"# {title}" + (f" ({style} style)" if style and d.name not in STYLE_DIRS else ""), ""]
    text = describe(rel)
    if text:
        lines += [text, ""]
    if subs:
        lines += ["## Folders", "", "| Folder | What is in it |", "|---|---|"]
        for s in subs:
            dd = describe(str(s.relative_to(KIT))) or ""
            lines.append(f"| [`{s.name}/`]({s.name}/) | {dd.split('. ')[0].rstrip('.') + '.' if dd else ''} |")
        lines.append("")
    shown = [f for f in files if f.name != "README.md"]
    if shown:
        lines += ["## Files", "", "| File | Size | Details |", "|---|---|---|"]
        for f in shown:
            lines.append(f"| `{f.name}` | {human(f.stat().st_size)} | {cache.get(f, '')} |")
        lines.append("")
    up = "../README.md" if rel else None
    if up:
        lines.append(f"Up one level: [{d.parent.name if d.parent != KIT else 'the kit'}]({up})")
    rd.write_text("\n".join(lines).rstrip() + "\n")
    return True


def manifest(tree, cache):
    total, count = 0, 0
    rows = []
    for d, (files, _) in tree.items():
        rel = "." if d == KIT else str(d.relative_to(KIT))
        if not files:
            continue
        rows += ["", f"### `{rel}/`", "", "| File | Size | Details |", "|---|---|---|"]
        for f in files:
            sz = f.stat().st_size
            total += sz
            count += 1
            rows.append(f"| `{f.name}` | {human(sz)} | {cache.get(f, '')} |")
    head = [MARK, "# MANIFEST", "", f"Every file in the kit: **{count} files, {human(total)}** "
            "(not counting the zips in `downloads/`, which hold copies of these same files, and the build's work folder `code/_work/`).", "",
            "Made by `python3 code/make_docs.py`. Run it again after changing anything and this list updates.", "",
            "Sizes use 1 MB = 1,000,000 bytes.", ""]
    (KIT / "MANIFEST.md").write_text("\n".join(head + rows) + "\n")
    return count, total


