def style_readme(d, key):
    cfg = json.loads((KIT / "brand-config.json").read_text())
    sc = cfg["styles"][key]
    lines = [MARK, f"# Style {sc['number']}: {sc['name']}", "", f"> {sc['tagline']}", "",
             f"**The feel:** {sc['feel']}.", "",
             "Start with [`overview.png`](overview.png) (everything on one sheet) and the brand guide in [`01_Brand-Guide/`](01_Brand-Guide/).", "",
             "## Colours", "", "| | Name | HEX | RGB | Share of a layout |", "|---|---|---|---|---|"]
    for role, c in sc["colours"].items():
        h = c["hex"].lstrip("#")
        rgb = ", ".join(str(int(h[i:i + 2], 16)) for i in (0, 2, 4))
        lines.append(f"| {role} | {c['name']} | `{c['hex']}` | {rgb} | about {sc.get('proportions', {}).get(role, '?')} % |")
    lines += ["", "## Type", "", f"- **Anton** (Regular) for the name, titles and big lines.",
              f"- **{TEXT[sc['fonts']['text']]}** (Regular, Medium, Bold) for small labels and anything you read.",
              "- Both are free for commercial use. See `../fonts.md`.", "",
              "## Sound", "", f"{SOUNDS[key].capitalize()}. Every intro ends on the two-note ASTRIS motif, in this style's voice.", "",
              "## Rules", ""] + [f"- {r}" for r in RULES[key]] + ["", "## What is in each section", "", "| Section | What is in it | A good first file |", "|---|---|---|"]
    for name, what, first in SECTIONS:
        f = first.format(k=key)
        lines.append(f"| [`{name}/`]({name}/) | {what} | [`{f.split('/')[-1]}`]({name}/{f}) |")
    lines += ["", "Everything in [SQUARE BRACKETS] is a placeholder: fill in `brand-config.json` and rebuild (see `../code/README.md`).", "",
              "Up one level: [the kit](../README.md)"]
    (d / "README.md").write_text("\n".join(lines) + "\n")


def large_files(cache):
    """The 'Large files' section of the top README: every file of 20 MB or more."""
    big = sorted([f for f in KIT.rglob("*") if f.is_file() and not any(p in SKIP_DIRS for p in f.relative_to(KIT).parts)
                  and "downloads" not in f.relative_to(KIT).parts and f.stat().st_size >= 20e6], key=lambda f: -f.stat().st_size)
    total = sum(f.stat().st_size for f in big)
    lines = ["## Large files", "",
             f"These {len(big)} files are 20 MB or more ({human(total)} together). All of them are stored with Git LFS, and every one is under 100 MB.",
             "The zip parts in `downloads/` are up to 95 MB each.", "", "| File | Size | Details |", "|---|---|---|"]
    lines += [f"| `{f.relative_to(KIT)}` | {human(f.stat().st_size)} | {cache.get(f, '')} |" for f in big]
    rd = KIT / "README.md"
    t = rd.read_text()
    a, b = t.index("<!-- large-files:start -->"), t.index("<!-- large-files:end -->")
    rd.write_text(t[:a] + "<!-- large-files:start -->\n" + "\n".join(lines) + "\n" + t[b:])


def main():
    tree = walk()
    cache = {}
    for d, (files, _) in tree.items():
        for f in files:
            cache[f] = details(f)
    n = 0
    for d, (files, subs) in tree.items():
        if d == KIT or d.name in STYLE_DIRS or str(d.relative_to(KIT)) in ("code", "downloads"):
            continue                                              # these have their own, hand-written READMEs
        n += write_readme(d, files, subs, cache)
    for d, key in ((KIT / k, v) for k, v in STYLE_DIRS.items()):
        style_readme(d, key)
    large_files(cache)
    tree = walk()                                                 # again, so the READMEs just written are listed too
    for d, (files, _) in tree.items():
        for f in files:
            if f not in cache:
                cache[f] = details(f)
    count, total = manifest(tree, cache)
    print(f"{n} READMEs written, MANIFEST.md lists {count} files ({human(total)})")


if __name__ == "__main__":
    main()
